public class DefaultClaims extends LinkedHashMap<String, Object> implements Claims {

    public DefaultClaims(Map<String, Object> map) {
        super(map);
    }

    @Override
    public String getSubject() {
        Object value = get(SUBJECT);
        return value == null ? null : value.toString();
    }

    @Override
    public void setSubject(String subject) {
        put(SUBJECT, subject);
    }

    @Override
    public Date getExpiration() {
        return dateValue(EXPIRATION);
    }

    @Override
    public Date getIssuedAt() {
        return dateValue(ISSUED_AT);
    }

    @Override
    public <T> T get(String claimName, Class<T> requiredType) {
        Object value = get(claimName);
        if (value == null) {
            return null;
        }
        if (!requiredType.isInstance(value)) {
            throw new io.jsonwebtoken.JwtException("Claim '" + claimName + "' is not of required type "
                    + requiredType.getName() + ".");
        }
        return requiredType.cast(value);
    }

    private Date dateValue(String claimName) {
        Object value = get(claimName);
        if (value instanceof Number number) {
            return new Date(number.longValue() * 1000L);
        }
        return null;
    }
